INSERT INTO `contactpage` (`id`, `slug`, `hero`, `contactInfo`, `liveSupport`, `contactForm`, `officeMap`, `offices`, `isPublished`, `createdAt`, `updatedAt`) VALUES
('cmsn6325c0000ux2ox16b5j5i', 'contact-us', '{\"titleNormal\":\"Let\'s\",\"titleHighlight\":\"Talk\",\"subtitle\":\"We\'re always happy to hear from you — whether it\'s a new project, a quick question, or just a hello.\"}', '{\"call\":{\"title\":\"Call Us\",\"enquiryLabel\":\"Enquiry:\",\"enquiryValue\":\"023 8097 0305\",\"supportLabel\":\"Support:\",\"supportValue\":\"023 8097 0305\"},\"write\":{\"title\":\"Write Us\",\"emails\":[\"hello@visualytes.com\",\"support@visualytes.com\"]},\"visit\":{\"title\":\"Visit Us\",\"addresses\":[\"Cumberland House, Southampton, SO15 2BG\",\"12 Shirley Road, Southampton, SO15 3EU\"]}}', '{\"badge\":\"REAL-TIME ASSISTANCE\",\"titleNormal\":\"Live\",\"titleHighlight\":\"Support\",\"description\":\"Do you need any urgent help from us regarding any of our services? Our dedicated support team is available for you.\",\"callLabel\":\"Call Us Now:\",\"callNumber\":\"023 8097 0305\",\"whatsappButtonText\":\"START WHATSAPP CHAT NOW!\",\"whatsappNote\":\"Requires WhatsApp Desktop to chat from a computer, or WhatsApp mobile app on your phone.\",\"image\":\"\",\"availabilityLabel\":\"AVAILABLE\",\"availabilityValue\":\"24/7\",\"responseTimeLabel\":\"RESPONSE TIME\",\"responseTimeValue\":\"< 2 min\"}', '{\"badge\":\"WE READ EVERY MESSAGE\",\"titleNormal\":\"Send Your\",\"titleHighlight\":\"Message\",\"submitButtonText\":\"Send Message\",\"clearButtonText\":\"Clear\"}', '{\"badge\":\"VISIT OUR TEAM\",\"title\":\"Our UK Office Locations\",\"embedUrl\":\"\"}', '{\"badge\":\"GLOBAL PRESENCE\",\"title\":\"Offices Across Continents\",\"groups\":[{\"title\":\"Delivery Centers\",\"locations\":[\"Southampton, United Kingdom\",\"London, United Kingdom\",\"Mumbai, India\",\"Ahmedabad, India\",\"Kolkata, India\",\"Noida, India\"]},{\"title\":\"Sales Offices\",\"locations\":[\"London, United Kingdom\",\"Mumbai, India\",\"Texas, USA\",\"Sydney, Australia\",\"United Arab Emirates\",\"Douglas, Isle of Man\"]},{\"title\":\"Corporate Offices\",\"locations\":[\"London, United Kingdom\",\"Basingstoke, United Kingdom\",\"Mumbai, India\"]}]}', 1, '2026-08-10 11:47:38.016', '2026-08-10 11:47:38.016');

