--
-- Dumping data for table `faq`
--

INSERT INTO `faq` (`id`, `question`, `answer`, `sortOrder`, `isActive`, `createdAt`, `updatedAt`) VALUES
('cmspuksrv0001uxhsw3qwk5uc', 'What domain name should I choose?', 'The choice of domain name depends on how you plan to use it. In most cases, it makes sense to choose one that is easy to pronounce and spell if you will be telling people about it over the phone. Above all, you should choose a name that is memorable and not confusing.', 0, 1, '2026-08-12 08:48:48.811', '2026-08-12 08:59:56.555'),
('cmspuksrv0002uxhss2v9iom5', 'What does Visualytes do?', 'Visualytes is a full-service digital agency specialising in web design, development, SEO, and digital marketing. We help businesses build high-performing websites, improve search visibility, and grow their online presence — from strategy through to launch and ongoing support.', 1, 1, '2026-08-12 08:48:48.811', '2026-08-12 08:49:22.760'),
('cmspuksrv0003uxhsg8tslvef', 'How long will it take for my website to be designed?', 'The time it takes to build a site depends on the complexity of the site. If you have a deadline, we will work hard to meet it. The most common cause of delay is the content (text/images) from the client.', 2, 1, '2026-08-12 08:48:48.811', '2026-08-12 08:48:48.811'),
('cmspuksrv0004uxhsfkq9roj6', 'Once my website design is completed, what after-sales service do you offer?', 'We fully support any website we design and are always available should you encounter any problems or require new enhancements. We also offer website hosting and maintenance.', 3, 1, '2026-08-12 08:48:48.811', '2026-08-12 08:48:48.811'),
('cmspuksrv0005uxhs1u8yfu29', 'What photo, graphics and text formats should I use for my new website?', 'Please provide all text, photos and graphics in electronic form. For example, the output from a digital camera, Microsoft Word or a digital scanner.', 4, 1, '2026-08-12 08:48:48.811', '2026-08-12 08:48:48.811'),
('cmspuksrv0006uxhs9ymkrjeu', 'Will my website design be search-engine friendly?', 'All our websites are created with search engines in mind, and all designs are compliant with search engine guidelines. It is a good idea for your website to be re-evaluated from time to time as search engines do alter their rules and algorithms.', 5, 1, '2026-08-12 08:48:48.811', '2026-08-12 08:48:48.811'),
('cmspuksrv0007uxhst7lp9vqw', 'How do I get my website on search engines, especially Google?', 'Modern search engines will find your site naturally through links from other websites. Google especially relies on your incoming links to determine popularity and relevance.', 6, 1, '2026-08-12 08:48:48.811', '2026-08-12 08:48:48.811'),
('cmspuksrv0008uxhs9bvesxki', 'What would be the deliverables by way of SEO project management?', 'Project proposal, keyword reports, activity plans, weekly progress reports, monthly ranking reports, and content recommendations.', 7, 1, '2026-08-12 08:48:48.811', '2026-08-12 08:48:48.811'),
('cmspuksrv0009uxhsgz6ciif0', 'Can you redesign an existing website?', 'Yes. We can redesign existing websites and retain your organization\'s style or provide a completely new modern design tailored to your brand and business goals.', 8, 1, '2026-08-12 08:48:48.811', '2026-08-12 10:25:13.928');

